function getSeoKeywordItems(path) {
  const page = seoKeywordPages[path];
  if (!page) return [];
  if (path === "/bangla-ebook") {
    return ebookData.slice(0, 12).map((item, index) => ({
      title: item.title,
      url: `${SITE_URL}/ebooks/read/${item.slug}`,
      category: "বাংলা ই-বুক",
      description: item.description || page.description,
      position: index + 1,
    }));
  }
  const terms = page.filterTerms || [];
  const matched = writingsData.filter((item) => {
    const haystack = `${item.title} ${item.category} ${item.preview} ${item.content}`;
    return terms.some((term) => haystack.includes(term));
  });
  const source = matched.length >= 6 ? matched : writingsData;
  return source.slice(0, 24).map((item, index) => ({
    title: item.title,
    url: `${SITE_URL}/writings/${item.slug}`,
    category: item.category || "বাংলা লেখা",
    description: item.preview || page.description,
    position: index + 1,
  }));
}

function buildBreadcrumbJsonLd(path, url) {
  const names = {
    "/about": "পরিচিতি",
    "/writings": "কবিতা ও লেখা",
    "/ebooks": "ই-বুক",
    "/news": "সরদার সংবাদ",
    "/contact": "যোগাযোগ",
    "/gallery": "গ্যালারি",
    "/facebook-recitations": "Facebook আবৃত্তি",
    "/amio-likhbo-bastobota": "আমিও লিখবো বাস্তবতা",
    "/editor": "ডিজাইন ফরম্যাট",
    "/image-upscaler": "ইমেজ আপসেলার",
  };
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: SITE_URL },
      { "@type": "ListItem", position: 2, name: names[path] || "Page", item: url },
    ],
  };
}

function buildCollectionItems(path) {
  if (path === "/writings") {
    return writingsData.slice(0, 25).map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      item: {
        "@type": "CreativeWork",
        name: item.title,
        url: `${SITE_URL}/writings/${item.slug}`,
        author: { "@id": `${SITE_URL}/#person` },
        genre: item.category,
        inLanguage: "bn-BD",
        description: item.preview,
      },
    }));
  }
  if (path === "/ebooks") {
    return ebookData.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      item: {
        "@type": "Book",
        name: item.title,
        url: `${SITE_URL}/ebooks/read/${item.slug}`,
        author: { "@id": `${SITE_URL}/#person` },
        image: item.image,
        inLanguage: "bn-BD",
        description: item.description,
      },
    }));
  }
  if (path === "/news") {
    return newsData.slice(0, 10).map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      item: {
        "@type": "NewsArticle",
        headline: item.title,
        url: `${SITE_URL}/news/${item.id}`,
        datePublished: toIsoDateTime(item.date),
        image: item.image,
        articleSection: item.category,
        description: item.excerpt,
      },
    }));
  }
  return [];
}

function buildRouteJsonLd(path, url, title, description) {
  const collectionRoutes = new Set(["/writings", "/ebooks", "/news", "/gallery", "/facebook-recitations", "/amio-likhbo-bastobota", "/editor", "/image-upscaler", ...Object.keys(seoKeywordPages)]);
  const contactRoutes = new Set(["/contact"]);
  const pageType = contactRoutes.has(path) ? "ContactPage" : collectionRoutes.has(path) ? "CollectionPage" : "WebPage";
  const graph = [
    buildSiteJsonLd(),
    buildPersonJsonLd(),
    {
      "@context": "https://schema.org",
      "@type": pageType,
      "@id": `${url}#webpage`,
      url,
      name: title,
      headline: title,
      description,
      inLanguage: "bn-BD",
      isPartOf: { "@id": `${SITE_URL}/#website` },
      about: { "@id": `${SITE_URL}/#person` },
      primaryImageOfPage: { "@type": "ImageObject", url: DEFAULT_IMAGE },
    },
  ];
  if (path !== "/" && path !== "") graph.push(buildBreadcrumbJsonLd(path, url));
  const items = buildCollectionItems(path);
  if (items.length) {
    graph.push({
      "@context": "https://schema.org",
      "@type": "ItemList",
      "@id": `${url}#itemlist`,
      name: title,
      itemListElement: items,
    });
  }
  return graph;
}

function normalizeJsonLd(jsonLd, path, url, title, description) {
  const base = buildRouteJsonLd(path, url, title, description);
  if (!jsonLd) return base;
  return Array.isArray(jsonLd) ? [...base, ...jsonLd] : [...base, jsonLd];
}

function buildNewsArticleJsonLd(news, url, image) {
  return {
    "@context": "https://schema.org",
    "@type": "NewsArticle",
    mainEntityOfPage: {
      "@type": "WebPage",
      "@id": url,
    },
    headline: news.title,
    description: news.excerpt,
    image: [image],
    datePublished: toIsoDateTime(news.date),
    dateModified: toIsoDateTime(news.date),
    author: {
      "@type": "Person",
      name: news.author || "মাহবুব সরদার সবুজ",
      url: SITE_URL,
    },
    publisher: {
      "@type": "Organization",
      name: NEWS_PUBLISHER_NAME,
      logo: {
        "@type": "ImageObject",
        url: NEWS_PUBLISHER_LOGO,
      },
    },
    articleSection: news.category,
    keywords: news.keywords || news.category,
    inLanguage: "bn-BD",
    isAccessibleForFree: true,
  };
}

